const setDeliveryStatus = `-- name: SetDeliveryStatus :execrows
UPDATE deliveries
SET status              = $1,
    arrived_shop_at     = CASE WHEN $1 = 'at_shop' THEN now() ELSE arrived_shop_at END,
    picked_up_at        = CASE WHEN $1 = 'picked_up' THEN now() ELSE picked_up_at END,
    arrived_customer_at = CASE WHEN $1 = 'at_customer' THEN now() ELSE arrived_customer_at END,
    delivered_at        = CASE WHEN $1 = 'delivered' THEN now() ELSE delivered_at END,
    failed_at           = CASE WHEN $1 = 'returning' THEN now() ELSE failed_at END,
    failure_reason      = CASE WHEN $1 = 'returning' THEN $2 ELSE failure_reason END,
    call_attempts       = greatest(call_attempts, $3::integer),
    ended_at            = CASE WHEN $1 IN ('delivered', 'returned', 'withdrawn', 'cancelled') THEN now() ELSE ended_at END,
    updated_at          = now()
WHERE id = $4 AND status = ANY($5::text[])
`

type SetDeliveryStatusParams struct {
	NewStatus     string
	FailureReason string
	CallAttempts  int32
	ID            uuid.UUID
	FromStatuses  []string
}

func (q *Queries) SetDeliveryStatus(ctx context.Context, arg SetDeliveryStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, setDeliveryStatus,
		arg.NewStatus,
		arg.FailureReason,
		arg.CallAttempts,
		arg.ID,
		arg.FromStatuses,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

